<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $proyectos = Illuminate\Support\Facades\DB::table("proyectos")->where("urg_id", "1")->where("ejercicio_id", 2026)->get(); foreach($proyectos as $p) { echo "Proyecto: $p->id - $p->nombre\n"; $actividades = Illuminate\Support\Facades\DB::table("actividades_sustantivas")->where("proyecto_id", $p->id)->get(); if($actividades->isEmpty()) { $actividades = Illuminate\Support\Facades\DB::table("acciones_sustantivas")->where("proyecto_id", $p->id)->get(); } foreach($actividades as $a) { $actId = $a->id ?? $a->accion_sustantiva_id ?? null; echo "  Accion $actId: " . substr($a->descripcion ?? $a->denominacion, 0, 40) . "...\n"; $riesgos = Illuminate\Support\Facades\DB::table("actividad_riesgo")->where("actividad_sustantiva_id", $actId)->get(); foreach($riesgos as $r) { echo "    -> Riesgo vinculado: $r->riesgo_id\n"; } } }
